const STAGE = 'ports';
const MAX_MINUTES = 240;
const BODY = "IPS="$R/discovery/ips.txt"
mkdir -p "$STATE" nmap
touch "$STATE/ports.txt"
: > naabu.jsonl
if [ -s "$IPS" ]; then
  timeout 120m sudo -n /usr/bin/naabu -list "$IPS" -top-ports 1000 -s s -rate "$PORT_RATE" -retries 1 \
    -exclude-cdn -silent -json -o naabu.jsonl >/dev/null 2>naabu.log || true
  touch naabu.jsonl
fi
jq -r 'select(.ip and .port) | "\(.ip):\(.port)"' naabu.jsonl 2>/dev/null | sort -u > open.txt
sort -u "$STATE/ports.txt" > known.txt
comm -23 open.txt known.txt > open.new.txt

python3 - open.new.txt > nmap_groups.txt <<'PY'
import ipaddress, sys
groups = {}
for line in open(sys.argv[1]):
    ip, _, port = line.strip().rpartition(":")
    try:
        ipaddress.ip_address(ip)
        p = int(port)
    except ValueError:
        continue
    if 0 < p < 65536:
        groups.setdefault(ip, set()).add(p)
for ip, ports in groups.items():
    print(ip, ",".join(str(p) for p in sorted(ports)))
PY

while read -r ip ports; do
  timeout 15m sudo -n /usr/bin/nmap -sV -sC -Pn -T4 --host-timeout 12m --script-timeout 60s \
    -p "$ports" -oX "nmap/$ip.xml" "$ip" >/dev/null 2>>nmap.log || true
done < nmap_groups.txt

python3 - <<'PY'
import glob, json
import xml.etree.ElementTree as ET
out = open("services.jsonl", "w")
n = 0
for path in glob.glob("nmap/*.xml"):
    try:
        root = ET.parse(path).getroot()
    except ET.ParseError:
        continue
    for host in root.iter("host"):
        addr = host.find("address")
        ip = addr.get("addr") if addr is not None else ""
        for p in host.iter("port"):
            st = p.find("state")
            if st is None or st.get("state") != "open":
                continue
            sv = p.find("service")
            sv = sv.attrib if sv is not None else {}
            scripts = {s.get("id"): (s.get("output") or "")[:300] for s in p.findall("script")}
            out.write(json.dumps({"ip": ip, "port": int(p.get("portid")), "proto": p.get("protocol"),
                                  "service": sv.get("name", ""), "product": sv.get("product", ""),
                                  "version": sv.get("version", ""), "extrainfo": sv.get("extrainfo", ""),
                                  "tunnel": sv.get("tunnel", ""), "scripts": scripts}) + "\n")
            n += 1
out.close()
PY

jq -nc --argjson open "$(wc -l < open.txt)" --argjson new "$(wc -l < open.new.txt)" \
  --argjson scanned "$(wc -l < nmap_groups.txt)" '{ports_open: $open, ports_new: $new, nmap_hosts: $scanned}' > result.json
";
const c = $input.first().json;
const SAFE = /^[A-Za-z0-9_./:-]+$/;
const q = (k) => {
  const v = String(c[k] ?? '');
  if (!SAFE.test(v)) throw new Error(`Unsafe or missing context value for ${k}: ${v}`);
  return `'${v}'`;
};
const int = (v, lo, hi, d) => Math.min(Math.max(parseInt(v ?? d, 10) || d, lo), hi);
const header = [
  '#!/usr/bin/env bash',
  'set -uo pipefail',
  `R=${q('run_dir')}`,
  `S=${q('run_dir').slice(0, -1)}/${STAGE}'`,
  `ENG=${q('engagement')}`,
  `RUN_ID=${q('run_id')}`,
  `STATE=${q('state_dir')}`,
  `RATE=${int(c.rate, 1, 500, 50)}`,
  `PORT_RATE=${int(c.port_rate, 50, 2000, 500)}`,
  `INTRUSIVE=${c.intrusive === true ? 1 : 0}`,
  `PERMUTE=${c.permute === true ? 1 : 0}`,
  'mkdir -p "$S" && cd "$S" || exit 1',
  ''
].join('
');
return [{ json: { job_dir: `${c.run_dir}/${STAGE}`, script: header + BODY, max_minutes: MAX_MINUTES } }];

const ctx = $('When Called').first().json;
const r = $input.first().json;
const stages = { ...(ctx.stages ?? {}), ports: { ...(r.result ?? {}), rc: r.rc, timed_out: r.timed_out } };
return [{ json: { ...ctx, stages } }];
